#!/usr/bin/env python3
"""Adds what OneSource Connect needs to the host projects generated by `flutter create`.

Run from the project root after `flutter create` (tool/bootstrap.sh does this). Safe to run twice.
"""
import pathlib
import plistlib
import re
import sys

root = pathlib.Path(__file__).resolve().parent.parent
changed = []

# ---- iOS: usage descriptions, languages, display name -------------------------------------------------------
plist_path = root / 'ios' / 'Runner' / 'Info.plist'
if plist_path.exists():
    with plist_path.open('rb') as f:
        plist = plistlib.load(f)
    plist.update({
        'CFBundleDisplayName': 'OneSource Connect',
        'CFBundleLocalizations': ['en', 'ar'],
        'NSFaceIDUsageDescription': 'Unlock OneSource Connect with Face ID. The app never receives an image of your face.',
        'NSCameraUsageDescription': 'Take photos to attach to a help request or as trip proof.',
        'NSPhotoLibraryUsageDescription': 'Choose photos to attach to a help request.',
        'NSLocationWhenInUseUsageDescription': 'Your company records where attendance is marked and where trip milestones happen.',
        'LSApplicationQueriesSchemes': ['https', 'tel'],
    })
    with plist_path.open('wb') as f:
        plistlib.dump(plist, f)
    changed.append(str(plist_path.relative_to(root)))
else:
    print('ios/Runner/Info.plist not found: run flutter create first', file=sys.stderr)

# ---- iOS: minimum version 13 (geolocator, local_auth) -------------------------------------------------------
podfile = root / 'ios' / 'Podfile'
if podfile.exists():
    text = podfile.read_text()
    new = re.sub(r"^#?\s*platform :ios, '[0-9.]+'", "platform :ios, '13.0'", text, flags=re.M)
    if new != text:
        podfile.write_text(new)
        changed.append(str(podfile.relative_to(root)))

# ---- Android: minSdk 24 (local_auth, geolocator) and an AppCompat launch theme ------------------------------
for name in ('build.gradle.kts', 'build.gradle'):
    gradle = root / 'android' / 'app' / name
    if gradle.exists():
        text = gradle.read_text()
        new = re.sub(r'minSdk(Version)?\s*=?\s*flutter\.minSdkVersion', lambda m: 'minSdk = 24' if name.endswith('kts') else 'minSdkVersion 24', text)
        if new != text:
            gradle.write_text(new)
            changed.append(str(gradle.relative_to(root)))

print('updated:', ', '.join(changed) if changed else 'nothing')
